with latest as (select *, row_number() over (partition by product_id order by sale_date desc, id) as row_num from store_sales qualify row_num = 1) select date_trunc('week', sale_date) as week_start, product_id, round(avg(revenue), 2) as avg_revenue, count(*) as num_rows, stddev_samp(revenue) as revenue_stddev, approx_percentile(units, 0.5) as units_p50, count(distinct product_id) as distinct_product_ids, bit_or(units) as units_bit_or from latest group by date_trunc('week', sale_date), product_id order by units_bit_or desc
